let s = AsyncThrowingStream<Int, Error> { c in
    c.yield(1)
    c.finish(throwing: CancellationError())
}
do { for try await v in s { print(v) } }
catch { print("failed") }

let s = AsyncStream<String> { continuation in
    continuation.yield("a")
    continuation.yield("b")
    continuation.finish()
}
for await x in s { print(x) }

let (s, c) = AsyncStream.makeStream(
    of: Int.self,
    bufferingPolicy: .bufferingNewest(2))
for i in 1...4 { c.yield(i) }
c.finish()
for await v in s { print(v) }

